    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    # Initialize the path dictionary
    paths = {node: [] for node in graph}
    paths[source] = [source]

    # Priority queue to hold nodes to be visited
    from heapq import heappush, heappop
    queue = [(0, source)]

    while queue:
        current_distance, current_node = heappop(queue)

        # If we reached the target, we can stop
        if current_node == target:
            return (current_distance, paths[target])

        # Skip the current node if we have already visited it with a better distance
        if current_distance > distances[current_node]:
            continue

        # Explore neighbors
        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            # Check if this is a shorter path to the neighbor
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                paths[neighbor] = paths[current_node] + [neighbor]
                heappush(queue, (distance, neighbor))

    # If we reached here, it means target is unreachable
    return (float('inf'), None)

