def shortest_path(graph, source, target):
    import heapq

    def dijkstra(graph, source):
        distances = {node: float('inf') for node in graph}
        distances[source] = 0
        priority_queue = [(0, source)]

        while priority_queue:
            current_distance, current_node = heapq.heappop(priority_queue)

            if current_node == target:
                return current_distance

            for neighbor, weight in graph[current_node]:
                distance = current_distance + weight

                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(priority_queue, (distance, neighbor))

        return float('inf')

    # Find the shortest distance from source to target
    shortest_distance = dijkstra(graph, source)

    # If there is no path, return infinity and None
    if shortest_distance == float('inf'):
        return float('inf'), None

    # Find the shortest path from source to target
    visited = {source}
    path = [target]
    current = target

    while current != source:
        for neighbor, _ in graph[current]:
            if neighbor not in visited:
                visited.add(neighbor)
                path.append(neighbor)
                current = neighbor
                break

    # The path is in reverse, so we need to reverse it
    path.reverse()

    return shortest_distance, path

