    while queue:
        current_distance, current_node = queue.popleft()

        # If we reached the target, reconstruct the path
        if current_node == target:
            path[target] = []
            while current_node in path:
                path[target].append(current_node)
                current_node = path[current_node][-2]
            path[target].reverse()
