from collections import deque
import sys

def shortest_path(graph, source, target):
    # Initialize distance and path dictionaries
    distances = {node: sys.maxsize for node in graph}
    path = {node: None for node in graph}
    distances[source] = 0

    # Priority queue to process nodes based on distance
    queue = deque([(source, 0)])

    while queue:
        current_node, current_distance = queue.popleft()

        # If we reached the target, reconstruct the path
        if current_node == target:
            path[target] = current_node
            return (current_distance, reconstruct_path(path, source, target))

        # Explore all neighbors
        for neighbor, weight in graph[current_node]:
            distance_through_current = current_distance + weight
            if distance_through_current < distances[neighbor]:
                distances[neighbor] = distance_through_current
                path[neighbor] = current_node
                queue.append((neighbor, distance_through_current))

    # If no path is found, return infinity and None
    return (float('inf'), None)


def reconstruct_path(path, start, end):
    """Reconstructs the path from start to end using the path dictionary."""
    result = []
    while end:
        result.append(end)
        end = path.get(end)
    result.reverse()
    return result

