from heapq import heappush, heappop

def shortest_path(graph, source, target):
    # We use a priority queue for Dijkstra's algorithm
    queue = [(0, source)]
    # To keep track of distances from the source
    distance_map = {node: float('inf') for node in graph}
    distance_map[source] = 0
    # To keep track of the actual path
    shortest_path_map = {source: [source]}

    while queue:
        current_distance, current_node = heappop(queue)

        if current_node == target:
            return (current_distance, shortest_path_map[target])

        for neighbor, weight in graph.get(current_node, []):
            distance = current_distance + weight
            if distance < distance_map[neighbor]:
                distance_map[neighbor] = distance
                shortest_path_map[neighbor] = shortest_path_map[current_node] + [neighbor]
                heappush(queue, (distance, neighbor))

    # If we leave the while loop, it means target is unreachable
    return (float('inf'), None)

# Example usage:
graph = {
    'A': [('B', 1), ('C', 4)],
    'B': [('A', 1), ('C', 2), ('D', 5)],
    'C': [('A', 4), ('B', 2), ('D', 1)],
    'D': [('B', 5), ('C', 1)]
}
source = 'A'
target = 'D'
print(shortest_path(graph, source, target))
